describe('File Upload - Unsupported File Type Error', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should display error message when uploading unsupported file type', () => {
    // Setup: intercept the file upload API call
    cy.intercept('POST', '/api/upload').as('uploadRequest');

    // Get the file input element
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/document.pdf', { force: true });

    // Verify file name is displayed
    cy.get('[data-testid="file-name"]').should('contain', 'document.pdf');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the API call
    cy.wait('@uploadRequest');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .should('contain', 'Unsupported file type');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]').should('be.visible');

    // Verify upload button is still enabled for retry
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');
  });

  it('should clear error message when user selects a supported file type', () => {
    // Setup: intercept the file upload API call
    cy.intercept('POST', '/api/upload').as('uploadRequest');

    // Upload unsupported file first
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/document.pdf', { force: true });
    cy.get('[data-testid="upload-button"]').click();
    cy.wait('@uploadRequest');

    // Verify error message is visible
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Clear the file input
    cy.get('[data-testid="file-input"]').clear();

    // Upload supported file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/image.png', { force: true });

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify file name is updated
    cy.get('[data-testid="file-name"]').should('contain', 'image.png');

    // Verify upload button is enabled
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');
  });
});
